  dialogues: [
    {
      id: 'argument-structure-dialogue',
      title: 'Debating Urban Development Policy',
      context: 'Two urban planners debate whether to preserve historic districts or allow modern development.',
      lines: [
        { speaker: 'Arslon', text: "I argue that preserving historic districts generates more long-term economic value than new construction.", translation: "Men tarixiy tumanlarni saqlash yangi qurilishdan ko'ra ko'proq uzoq muddatli iqtisodiy qiymat yaratadi deb ta'kidlayman." },
        { speaker: 'Lobar', text: "While I concede that heritage is important, we cannot ignore the housing needs of a growing population.", translation: "Meros muhimligini tan olsam ham, o'sib borayotgan aholining uy-joy ehtiyojlarini e'tiborsiz qoldirolmaymiz." },
        { speaker: 'Arslon', text: "The evidence clearly demonstrates that heritage tourism generates three times more revenue per square metre than retail.", translation: "Dalillar meros turizmi kvadrat metrga chakana savdodan uch baravar ko'proq daromad keltirishini aniq ko'rsatadi." },
        { speaker: 'Lobar', text: "That may be true in central areas, but the argument does not apply to peripheral neighbourhoods.", translation: "Bu markaziy hududlarda to'g'ri bo'lishi mumkin, ammo bu dalil chekka mahallalarga taalluqli emas." },
        { speaker: 'Arslon', text: "Therefore, I propose a compromise: protect historic cores while allowing controlled development on the outskirts.", translation: "Shuning uchun, men murosani taklif qilaman: chekka hududlarda nazorat ostida rivojlanishga ruxsat berish bilan birga tarixiy markazlarni himoya qilish." },
      ],
    },
  ],
