  tests: [
    { id: 65081, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'Approximately' qanday stance marker?", blanks: ["Approximator"], explanation: "Approximately = taxminan (yaqinlashtiruvchi). Qoida: 'Approximately' = roughly, about. Aniq raqam o'rniga taxminiy: Approximately 50 people attended. (Taxminan 50 kishi qatnashdi.)" },
    { id: 65082, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Evaluative stance nima?", blanks: ["Faktga yozuvchining bahosini bildiradi"], explanation: "Evaluative = writer's judgment/attitude toward the fact" },
    { id: 65083, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Qaysi so'z evaluative?", blanks: ["unfortunately"], explanation: "'Unfortunately' = negative evaluative stance" },
    { id: 65084, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'Fewer than' qachon ishlatiladi?", blanks: ["Countable nouns bilan"], explanation: "Fewer than = countable; less than = uncountable/amount" },
    { id: 65085, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Qaysi so'z ishonch darajasi eng past?", blanks: ["tentatively"], explanation: "'Tentatively' = very low certainty (25%)" },
    { id: 65086, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Which sentence is correct?", options: ["Remarkably, the results were positive.", "Remarkably the results were positive.", "Remarkably, the results was positive.", "Remarkable, the results were positive."], correct: "Remarkably, the results were positive.", explanation: "Stance adverb + comma at sentence start" },
    { id: 65087, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'The drug appears to reduce inflammation.' — Bu qanday stance?", blanks: ["Hedged epistemic"], explanation: "'Appears to' = hedge verb = low-certainty epistemic stance" },
    { id: 65088, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Qaysi gap grammatik jihatdan to'g'ri?", blanks: ["Roughly half of participants agreed."], explanation: "Only one approximator = correct" },
    { id: 65089, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Which shows the HIGHEST certainty about evidence?", options: ["The data clearly demonstrates...", "clearly data The demonstrates...", "demonstrates... data clearly The", "The demonstrates... clearly data"], correct: "The data clearly demonstrates...", explanation: "'Clearly' = high certainty epistemic stance (100%). 'Demonstrates' = strongest reporting verb. Birgalikda eng kuchli ishonch darajasini ko'rsatadi." },
    { id: 65090, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'It is arguably the most effective treatment.' — Bu nima?", blanks: ["Hedged strong claim (epistemic)"], explanation: "'Arguably' = epistemic hedge: strong but not absolute claim" },
    { id: 65091, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Qaysi iborada XATO bor?", options: ["Certainly possibly, the drug is effective.", "Certainly possibly, the drug was effective.", "Certainly possibly, the drug is not effective.", "Certainly possibly, the drug isn't effective."], correct: "Certainly possibly, the drug is effective.", explanation: "'Certainly' (100% ishonch) va 'possibly' (50%) birga qo'llanilmaydi — qarama-qarshi certainty markers. Bittasini tanlash kerak: 'Certainly the drug is effective' YOKI 'Possibly the drug is effective'." },
    { id: 65092, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "'Strikingly, no side effects were observed.' — Nima ma'no?", options: ['Bu natijalarga ishonilmadi', "Bu natijalar kutilgandan farq qildi va e'tiborni tortdi", 'Bu natijalar zararli edi', 'Bu natijalar kutilgandek edi'], correct: "Bu natijalar kutilgandan farq qildi va e'tiborni tortdi", explanation: "'Strikingly' = surprising contrast — noteworthy deviation from expected" },
    { id: 65093, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Qaysi so'z epistemic?", blanks: ["presumably"], explanation: "'Presumably' = epistemic: based on assumption/logic" },
    { id: 65094, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Qaysi jumla eng to'g'ri akademik uslubda?", options: ["I think maybe this might possibly work.", "Obviously everyone agrees this works.", "The data tentatively suggests this approach may yield positive outcomes.", "This is clearly certainly the best solution ever."], correct: "The data tentatively suggests this approach may yield positive outcomes.", explanation: 'Qoida: Appropriate academic balance: Tentatively + may (ehtiyotkor), The data suggests (shaxssiz). \'The data suggests\' = 100% ishonch emas, balki ma\'lumotga asoslangan taklif.' },
    { id: 65095, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'Overwhelmingly' qanday ma'no?", blanks: ["Katta ko'pchilik bilan, qat'iy ravishda"], explanation: "'Overwhelmingly' = by a very large margin; strong degree adverb" },
    { id: 65096, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Qaysi gapda IKKITA XATO bor?", options: ["Remarkably the results shows a significant improvement.", "Remarkably, the results show a significant improvement.", "Remarkably, the results shows significant improvement.", "Remarkably, the results show significant improvements."], correct: "Remarkably the results shows a significant improvement.", explanation: 'Qoida: 1) \'Remarkably\' dan keyin vergul kerak: Remarkably, ... 2) \'Results\' ko\'plik, shuning uchun \'show\' (shows emas): results show (plural subject + plural verb). Subject-verb agreement!' },
    { id: 65097, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Stance marker ishlatish qaysi maqsadga xizmat qiladi?", blanks: ["Yozuvchining ishonchliligi va akademik aniqligi"], explanation: "Stance markers = precision + credibility in academic writing" },
    { id: 65098, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "'Fewer than 10 percent' va 'less than 10 percent' — qaysi farq bor?", options: ['Farq yo\'q — ikkalasi ham to\'g\'ri', "'Fewer' countable, 'less' uncountable — bu yerda both correct for percent", "'Fewer' noto'g'ri foiz bilan", "'Less' noto'g'ri foiz bilan"], correct: "'Fewer' countable, 'less' uncountable — bu yerda both correct for percent", explanation: 'Qoida: Percentage bilan \'fewer\' ham, \'less\' ham to\'g\'ri. \'Fewer\' sanaladigan: fewer people. \'Less\' sanalmas: less water. Percent = sanalmas, lekin ikkalasi ham qabul qilinadi.' },
    { id: 65099, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Eng formal approximator qaysi?", blanks: ["approximately"], explanation: "approximately > roughly > around > about (formality scale)" },
    { id: 65100, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Which sentence best demonstrates academic stance mastery?", options: ["I think maybe everyone agrees that exercise helps.", "Exercise definitely always cures all mental illness.", "Evidence overwhelmingly suggests that regular physical activity tends to significantly reduce symptoms of anxiety and depression across most demographic groups.", "Obviously exercise is good, certainly everyone knows this."], correct: "Evidence overwhelmingly suggests that regular physical activity tends to significantly reduce symptoms of anxiety and depression across most demographic groups.", explanation: 'Qoida: Optimal academic formula: Overwhelmingly (daraja) + Suggests (ehtiyotkorlik) + Tends to (ehtiyotkorlik) + Most (yaqinlashtiruvchi). To\'rt xil ehtiyotkorlik elementi birgalikda ideal akademik balans.' },
  ],
